func NewNullableDriverSummary(val *DriverSummary) *NullableDriverSummary {
	return &NullableDriverSummary{value: val, isSet: true}
}

func (v NullableDriverSummary) MarshalJSON() ([]byte, error) {
	return json.Marshal(v.value)
}

func (v *NullableDriverSummary) UnmarshalJSON(src []byte) error {
	v.isSet = true
	return json.Unmarshal(src, &v.value)
}
